(x, y, t) => {
  const w1x = Math.sin(y*0.012+t*0.2)*22+Math.cos(x*0.008-t*0.15)*16;
  const w1y = Math.cos(x*0.015-t*0.18)*20+Math.sin(y*0.01+t*0.22)*13;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.022-t*0.3)*9+Math.cos(mx*0.016+t*0.25)*7;
  const w2y = Math.cos(mx*0.019+t*0.28)*8+Math.sin(my*0.014-t*0.32)*6;
  const wx = mx+w2x, wy = my+w2y;
  const src = [
    [120+Math.sin(t*0.4)*80,60+Math.cos(t*0.3)*40,0.07,1.8,0],
    [360+Math.cos(t*0.35)*70,80+Math.sin(t*0.45)*50,0.09,2.1,1],
    [240+Math.sin(t*0.25+2)*100,120+Math.cos(t*0.4+1)*60,0.055,1.6,2],
    [80+Math.cos(t*0.5+1)*60,180+Math.sin(t*0.35+3)*50,0.11,2.4,0],
    [400+Math.sin(t*0.3+4)*70,160+Math.cos(t*0.55+2)*60,0.065,1.9,1],
    [200+Math.cos(t*0.28+5)*90,200+Math.sin(t*0.38)*70,0.08,2.0,2],
    [300+Math.sin(t*0.42+3)*50,40+Math.cos(t*0.32+4)*30,0.1,2.3,0],
    [160+Math.cos(t*0.22+6)*110,140+Math.sin(t*0.48+2)*80,0.06,1.7,1]
  ];
  let act=0,inh=0,mod=0;
  for(const[sX,sY,f,sp,tp]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    act+=Math.sin(d*f-t*sp)*(1+tp*0.2);
    inh+=Math.sin(d*f*0.6+t*sp*0.5+tp*2.1)*(1.2-tp*0.15);
    mod+=Math.sin(d*f*0.3-t*sp*0.8+tp*4)*0.5;
  }
  act/=8;inh/=8;mod/=8;
  const turb=(Math.sin(wx*0.03+wy*0.02+t*0.6)+Math.sin(wx*0.05-wy*0.04+t*0.9)*0.5+Math.sin(wx*0.08+wy*0.06-t*1.3)*0.25+Math.sin(wx*0.13-wy*0.1+t*1.8)*0.125)/1.875;
  const cx=240,cy=120,dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.04-ang*3-t*1.2)+Math.sin(dist*0.06+ang*2+t*0.9)*0.6)*0.35;
  const feed=act*0.6+turb*0.25+spiral*0.15+mod*0.1;
  const kill=inh*0.7+Math.sin(turb*2+t)*0.15;
  const reaction=Math.tanh((feed-kill)*2.5);
  const fine=Math.sin(wx*0.2)*Math.sin(wy*0.2)+Math.sin((wx+wy)*0.15+t)*0.3;
  const cell=Math.tanh(fine*1.2)*0.15;
  const blend=reaction*0.8+cell*0.2;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,90,105],[25,140,130],[45,175,140],[120,195,120],[195,200,90],[220,175,75],[215,130,70],[190,80,75],[140,45,75],[70,25,70],[30,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.55?1.12+Math.sin(reaction*Math.PI*2)*0.1:1.0;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
